import 'feed.dart';

class RegisterScreen extends StatefulWidget {
  const RegisterScreen({super.key});

  @override
  State<RegisterScreen> createState() => _RegisterScreenState();
}

class _RegisterScreenState extends State<RegisterScreen> {
  final TextEditingController emailController = TextEditingController();
  final TextEditingController passwordController = TextEditingController();
  final TextEditingController confirmPasswordController =
      TextEditingController();

  @override
  void dispose() {
    emailController.dispose();
    passwordController.dispose();
    confirmPasswordController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(),
      body: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 24),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            const Icon(
              Icons.push_pin,
              size: 56,
              color: Colors.red,
            ),
            const SizedBox(height: 16),
            const Text(
              'Crea tu cuenta',
              style: TextStyle(
                fontSize: 26,
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 32),

            TextField(
              controller: emailController,
              decoration: InputDecoration(
                hintText: 'Correo',
                filled: true,
                fillColor: Colors.grey[200],
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                  borderSide: BorderSide.none,
                ),
              ),
            ),
            const SizedBox(height: 16),

            TextField(
              controller: passwordController,
              obscureText: true,
              decoration: InputDecoration(
                hintText: 'Contraseña',
                filled: true,
                fillColor: Colors.grey[200],
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                  borderSide: BorderSide.none,
                ),
              ),
            ),
            const SizedBox(height: 16),

            TextField(
              controller: confirmPasswordController,
              obscureText: true,
              decoration: InputDecoration(
                hintText: 'Confirmar contraseña',
                filled: true,
                fillColor: Colors.grey[200],
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                  borderSide: BorderSide.none,
                ),
              ),
            ),
            const SizedBox(height: 20),
            SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.red,
                  padding: const EdgeInsets.symmetric(vertical: 14),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(24),
                  ),
                ),
                onPressed: _registerUser,
                child: const Text(
                  'Crear cuenta',
                  style: TextStyle(fontSize: 16),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Future <void> _registerUser() async {
    if (passwordController.text.trim() !=
        confirmPasswordController.text.trim()) {
      _showError('Las contraseñas no coinciden');
      return;
    }
    try {
      UserCredential userCredential =
      await authService.value.createAccount(
      email: emailController.text.trim () , 
      password: passwordController.text.trim());
      final uid =userCredential.user!.uid;

      await FirebaseFirestore.instance.
      collection('users').
      doc(uid).
      set({
        'email': emailController.text.trim(),
        'username': emailController.text.split('@')[0],
        'photoUrl': '',
        'createdAt': Timestamp.now(),
    });

      Navigator.pushReplacement(
        context,
        MaterialPageRoute(builder: (_) => const Feed()),
      );
    }    
    on FirebaseAuthException catch (e) {
    if (e.code == 'email-already-in-use') {
      _showError('Este correo ya está registrado');
    } else if (e.code == 'weak-password') {
      _showError('La contraseña es muy débil');
    } else {
      _showError(e.message ?? 'Error');
    }
  }


  }

  void _showError(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message)),
    );
  }
}

import 'dart:convert';
import 'package:http/http.dart' as http;

class UnsplashService {
  static const String _accessKey = '6dTFsBD3tKyNBwRyd4reg79ER2CIIbU-PIeh7d62yH0';

  Future<List<String>> fetchImages({String query = 'inspiration'}) async {
    final url = Uri.parse(
      'https://api.unsplash.com/search/photos'
      '?query=$query'
      '&per_page=30'
      '&client_id=$_accessKey',
    );

    final response = await http.get(url);

    if (response.statusCode != 200) {
      throw Exception('Error al cargar imágenes');
    }

    final data = json.decode(response.body);
    final results = data['results'] as List;

    return results
        .map((img) => img['urls']['regular'] as String)
        .toList();
  }
}

import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'package:google_sign_in/google_sign_in.dart';
ValueNotifier <AuthService> authService = ValueNotifier(AuthService());
class AuthService {
  final FirebaseAuth _auth = FirebaseAuth.instance;
  User? get currentUser => _auth.currentUser;
  Stream <User?> get authStateChanges => _auth.authStateChanges();
  Future <void> signIn (
    {required String email, required String password}
  ) async {
    await _auth.signInWithEmailAndPassword(
      email: email, password: password);
  }
  Future <UserCredential> createAccount ({
    required String email, required String password
  }
  ) async {
    return await _auth.createUserWithEmailAndPassword(
      email: email, password: password);
  } 
  Future <void> signOut() async {
    await _auth.signOut();
  }
  Future <void> resetPassword({
    required String email
  }) async {
    await _auth.sendPasswordResetEmail(email: email);
  }
  Future <void> updateUsername({
    required String username
  }) async {
    await currentUser?.updateDisplayName(username);
  }
  Future <void> deleteAccount({
    required String email, required String password
  }) async {
    AuthCredential credential = EmailAuthProvider.credential(email: email, password: password);
    await currentUser!.reauthenticateWithCredential(credential);
    await currentUser!.delete();
    await _auth.signOut();
  }
  Future <void> resetPasswordFromCurrentPassword({
    required String currentPassword, 
    required String newPassword,
    required String email,
  }) async{
    AuthCredential credential = EmailAuthProvider.credential(email: email, password: currentPassword);
    await currentUser!.reauthenticateWithCredential(credential);
    await currentUser!.updatePassword(newPassword);

  }

    Future<void> signInWithGoogle() async {
    final GoogleSignIn _googleSignIn = GoogleSignIn();
    final GoogleSignInAccount? googleUser = await _googleSignIn.signIn();
    if (googleUser == null) return;
    final GoogleSignInAuthentication googleAuth =
        await googleUser.authentication;
    final credential = GoogleAuthProvider.credential(
      accessToken: googleAuth.accessToken,
      idToken: googleAuth.idToken,
    );
    await _auth.signInWithCredential(credential);
  }

}

